import { BlockStack, Box, Text, Link } from "@xco-agency/corex-ui";
import type { AnnotatedSectionPropsType } from "../types";

export function AnnotatedSection({
  title,
  description,
  action,
  children,
}: AnnotatedSectionPropsType) {
  return (
    <div style={{ display: "flex", flexWrap: "wrap", gap: "24px" }}>
      <div style={{ flex: "1 1 260px", maxWidth: "340px" }}>
        <BlockStack gap="200">
          <Text as="h2" heading>
            {title}
          </Text>
          <Text as="p" tone="neutral">
            {description}
          </Text>
          {action ? (
            <Box padding="100">
              <Link
                url={action.url}
                external={Boolean(action.url)}
                onClick={action.onAction}
              >
                {action.content}
              </Link>
            </Box>
          ) : null}
        </BlockStack>
      </div>

      <div style={{ flex: "2 1 420px", minWidth: "280px" }}>{children}</div>
    </div>
  );
}

import * as React from "react";
import {
  Card,
  BlockStack,
  InlineStack,
  Banner,
  Button,
  Text,
} from "@xco-agency/corex-ui";

export type DangerZoneCardPropsType = {
  onReset?: () => void;
};

export function DangerZoneCard({ onReset }: DangerZoneCardPropsType) {
  const [confirming, setConfirming] = React.useState(false);

  return (
    <Card title="Danger zone">
      <BlockStack gap="400">
        <Banner title="Reset all configuration to defaults" tone="critical">
          <Text as="p">
            This action will revoke active API tokens, reset notification webhook
            bindings, and restore original store preferences. This action cannot be
            undone.
          </Text>
        </Banner>

        <InlineStack justifyContent="start" gap="300">
          {confirming ? (
            <InlineStack gap="200">
              <Button
                variant="primary"
                tone="critical"
                onClick={() => {
                  setConfirming(false);
                  onReset?.();
                }}
              >
                Yes, confirm reset
              </Button>
              <Button variant="secondary" onClick={() => setConfirming(false)}>
                Cancel
              </Button>
            </InlineStack>
          ) : (
            <Button
              variant="secondary"
              tone="critical"
              onClick={() => setConfirming(true)}
            >
              Reset store settings
            </Button>
          )}
        </InlineStack>
      </BlockStack>
    </Card>
  );
}

