import {
  Card,
  BlockStack,
  Banner,
  Checkbox,
  Select,
  Divider,
} from "@xco-agency/corex-ui";
import type { NotificationSettingsFormType } from "../types";

export type NotificationSettingsCardPropsType = {
  data: NotificationSettingsFormType;
  onChange: <K extends keyof NotificationSettingsFormType>(
    field: K,
    value: NotificationSettingsFormType[K],
  ) => void;
};

export function NotificationSettingsCard({
  data,
  onChange,
}: NotificationSettingsCardPropsType) {
  return (
    <Card title="Customer notifications">
      <BlockStack gap="400">
        <Banner title="Shopify notifications active" tone="info">
          Automated customer emails are processed directly through Shopify&apos;s webhook
          infrastructure with high deliverability guarantees.
        </Banner>

        <BlockStack gap="300">
          <Checkbox
            label="Send order confirmation emails"
            checked={data.orderConfirmationEmail}
            onChange={(checked) => onChange("orderConfirmationEmail", checked)}
            helpText="Sends an immediate receipt to the buyer once payment completes."
          />

          <Checkbox
            label="Send shipping updates via SMS"
            checked={data.shippingUpdatesSms}
            onChange={(checked) => onChange("shippingUpdatesSms", checked)}
            helpText="Notifies customers on carrier tracking updates and delivery milestones."
          />

          <Checkbox
            label="Low inventory notifications"
            checked={data.inventoryAlerts}
            onChange={(checked) => onChange("inventoryAlerts", checked)}
            helpText="Triggers an alert when a product variant drops below 5 units."
          />
        </BlockStack>

        <Divider />

        <BlockStack gap="300">
          <Checkbox
            label="Weekly performance digest"
            checked={data.weeklyDigest}
            onChange={(checked) => onChange("weeklyDigest", checked)}
            helpText="Receive a curated summary of sales, refunds, and cart conversions."
          />

          {data.weeklyDigest && (
            <Select
              label="Delivery schedule"
              value={data.digestFrequency}
              onChange={(val) => onChange("digestFrequency", val)}
              options={[
                { label: "Every Monday at 9:00 AM", value: "monday_morning" },
                { label: "Every Friday at 5:00 PM", value: "friday_afternoon" },
                { label: "First day of each month", value: "monthly" },
              ]}
            />
          )}
        </BlockStack>
      </BlockStack>
    </Card>
  );
}

import {
  Card,
  BlockStack,
  InlineStack,
  TextField,
  Checkbox,
  Badge,
  Button,
  Divider,
  Text,
} from "@xco-agency/corex-ui";
import type { SecuritySettingsFormType } from "../types";

export type SecuritySettingsCardPropsType = {
  data: SecuritySettingsFormType;
  onChange: <K extends keyof SecuritySettingsFormType>(
    field: K,
    value: SecuritySettingsFormType[K],
  ) => void;
};

export function SecuritySettingsCard({ data, onChange }: SecuritySettingsCardPropsType) {
  return (
    <Card title="Security & API credentials">
      <BlockStack gap="400">
        <InlineStack gap="200" align="start" alignItems="center">
          <Text as="span" tone="neutral">
            Environment mode:
          </Text>
          <Badge tone="info">Production</Badge>
        </InlineStack>

        <BlockStack gap="300">
          <Checkbox
            label="Enforce two-factor authentication (2FA) for staff"
            checked={data.requireTwoFactor}
            onChange={(checked) => onChange("requireTwoFactor", checked)}
            helpText="All collaborator accounts must have an authenticator app linked."
          />

          <Checkbox
            label="Enable REST & GraphQL API access"
            checked={data.apiAccessEnabled}
            onChange={(checked) => onChange("apiAccessEnabled", checked)}
            helpText="Permits external webhook subscribers and headless storefront queries."
          />
        </BlockStack>

        <Divider />

        <BlockStack gap="200">
          <TextField
            label="Webhook signing secret"
            value={data.webhookSecret}
            onChange={(val) => onChange("webhookSecret", val)}
            helpText="Used to verify HMAC SHA256 signatures on incoming payload headers."
          />
          <InlineStack align="start">
            <Button
              variant="secondary"
              onClick={() => {
                const randomSecret = `whsec_${Math.random().toString(36).slice(2, 18)}`;
                onChange("webhookSecret", randomSecret);
              }}
            >
              Rotate secret key
            </Button>
          </InlineStack>
        </BlockStack>

        <TextField
          label="IP Whitelist (optional)"
          value={data.ipWhitelist}
          onChange={(val) => onChange("ipWhitelist", val)}
          placeholder="192.168.1.1, 10.0.0.0/24"
          helpText="Comma-separated list of IPv4 or CIDR blocks authorized for admin API calls."
        />
      </BlockStack>
    </Card>
  );
}

import { Box, Card, InlineStack, Text, Button, Badge } from "@xco-agency/corex-ui";

export type SettingsSaveBarPropsType = {
  isDirty: boolean;
  isSaving: boolean;
  onSave: () => void;
  onDiscard: () => void;
};

export function SettingsSaveBar({
  isDirty,
  isSaving,
  onSave,
  onDiscard,
}: SettingsSaveBarPropsType) {
  if (!isDirty) return null;

  return (
    <Box padding="400">
      <Card>
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            flexWrap: "wrap",
            gap: "16px",
          }}
        >
          <InlineStack gap="200" align="start" alignItems="center">
            <Badge tone="warning">Unsaved changes</Badge>
            <Text as="span">You have unsaved changes in this section.</Text>
          </InlineStack>

          <InlineStack gap="200" align="end" alignItems="center">
            <Button variant="secondary" disabled={isSaving} onClick={onDiscard}>
              Discard
            </Button>
            <Button variant="primary" loading={isSaving} onClick={onSave}>
              Save changes
            </Button>
          </InlineStack>
        </div>
      </Card>
    </Box>
  );
}

